var SingerCore=(()=>{
'use strict';
const rules=Object.freeze({targetLower:60,targetUpper:90,discountPerDay:.0015,maxDiscount:.12,maxUplift:.01,shortDom:30});
const analysesKey='immobrain-singer-analyses-v1',referencesKey='immobrain-singer-references-v1';
function number(value){if(value===null||value===undefined||String(value).trim()==='')return null;let s=String(value).trim().replace(/[\s\u00a0€%]/g,'').replace(/EUR/ig,'');if(s.includes(','))s=s.replace(/\./g,'').replace(',','.');else if(/^\d{1,3}(\.\d{3})+$/.test(s))s=s.replace(/\./g,'');if(!/^-?\d+(?:\.\d+)?$/.test(s))return null;const n=Number(s);return Number.isFinite(n)?n:null}
const header=s=>String(s||'').replace(/^\uFEFF/,'').trim().toLowerCase().replace(/<[^>]*>/g,'').replace(/²/g,'2').replace(/\s+/g,' ');
function csv(text){text=String(text).replace(/^\uFEFF/,'');if(text.length>5*1024*1024)throw Error('CSV ist zu groß. Maximal 5 MB.');const line=text.split(/\r?\n/)[0]||'',counts={';':0,',':0,'\t':0};let quote=false;for(let i=0;i<line.length;i++){if(line[i]==='"'){if(quote&&line[i+1]==='"'){i++;continue}quote=!quote}else if(!quote&&line[i] in counts)counts[line[i]]++}const delimiter=Object.keys(counts).sort((a,b)=>counts[b]-counts[a])[0];if(!counts[delimiter])throw Error('Keine CSV-Spalten erkannt.');const rows=[];let row=[],cell='',quoted=false,closed=false;function pushRow(){row.push(cell);if(row.some(v=>v.trim()!==''))rows.push(row);row=[];cell='';closed=false;if(rows.length>10001)throw Error('Maximal 10.000 Angebote je CSV.')}for(let i=0;i<text.length;i++){const c=text[i];if(quoted){if(c==='"'){if(text[i+1]==='"'){cell+='"';i++}else{quoted=false;closed=true}}else cell+=c;continue}if(c==='"'){if(cell!=='')throw Error('Ungültige Anführungszeichen in CSV.');quoted=true;continue}if(c===delimiter){row.push(cell);cell='';closed=false;continue}if(c==='\n'||c==='\r'){if(c==='\r'&&text[i+1]==='\n')i++;pushRow();continue}if(closed&&!/\s/.test(c))throw Error('Ungültige CSV nach einem Textfeld.');if(!closed)cell+=c}if(quoted)throw Error('Nicht geschlossenes Textfeld in CSV.');if(cell||row.length)pushRow();if(rows.length<2)throw Error('CSV enthält keine Angebote.');return rows}
function parse(text){const data=csv(text),headers=data.shift().map(header),find=names=>headers.findIndex(h=>names.includes(h)),at={zip:find(['plz','postleitzahl','zipcode']),city:find(['ort','stadt','city']),rooms:find(['zi','zimmer','zimmeranzahl','rooms']),dom:find(['tage online','dom','days on market','vermarktungsdauer']),sqm:find(['preis/m2','preis pro m2','€/m2','eur/m2']),price:find(['preis','kaufpreis']),area:find(['wfl.','wfl','wohnfläche','wohnflaeche']),active:find(['aktiv','active']),id:find(['details']),kind:find(['objektart','typ'])};if(at.dom<0||at.sqm<0&&(at.price<0||at.area<0))throw Error('Es fehlen „Tage online“ und/oder Preisangaben („Preis/m²“ oder „Preis“ + „Wfl.“).');if(at.zip<0||at.rooms<0)throw Error('Für die Zuordnung fehlen PLZ oder Zimmeranzahl („Zi“).');const inferred=headers.includes('wohnungstyp')?'wohnung':headers.includes('haustyp')?'haus':'';const rows=[],seen=new Set();let invalid=0,duplicates=0;for(const [i,raw]of data.entries()){if(raw.length!==headers.length){invalid++;continue}const get=k=>at[k]<0?'':raw[at[k]].trim(),id=get('id');if(id&&seen.has(id)){duplicates++;continue}if(id)seen.add(id);let sqm=number(get('sqm'));const price=number(get('price')),area=number(get('area'));if(!(sqm>0)&&price>0&&area>0)sqm=price/area;const dom=number(get('dom')),rooms=number(get('rooms')),zip=get('zip');if(!(sqm>0&&sqm<=1e8)||!(dom!==null&&dom>=0&&dom<=10000)||!(rooms>0&&rooms<=1000)||!/^\d{5}$/.test(zip)){invalid++;continue}const activeRaw=header(get('active')),active=at.active<0?null:['ja','true','1','yes'].includes(activeRaw)?true:['nein','false','0','no'].includes(activeRaw)?false:null;rows.push({zipcode:zip,city:get('city').slice(0,150),rooms,kind:kind(get('kind'))||inferred,price:sqm,dom,active,row:i+2})}if(!rows.length)throw Error('Keine Angebote mit gültigem Preis, DOM, PLZ und Zimmeranzahl gefunden.');return {rows,total:data.length,invalid,duplicates,hasActive:at.active>=0}}
function kind(v){const s=String(v||'').toLowerCase();return /wohnung|appart|apartment/.test(s)?'wohnung':/haus|häuser|house/.test(s)?'haus':''}
function select(rows,filters){return (rows||[]).filter(r=>r.zipcode===filters.zipcode&&r.rooms===Number(filters.rooms)&&(!r.kind||r.kind===filters.kind)&&(!filters.activeOnly||r.active===true))}
function average(rows){if(!rows.length)return null;return {price:rows.reduce((s,r)=>s+r.price,0)/rows.length,dom:rows.reduce((s,r)=>s+r.dom,0)/rows.length,count:rows.length}}
function corridor(price,dom){if(price===null||price===undefined||price===''||dom===null||dom===undefined||dom==='')throw Error('Preis und Vermarktungsdauer fehlen.');price=Number(price);dom=Number(dom);if(!Number.isFinite(price)||price<=0||price>1e8||!Number.isFinite(dom)||dom<0||dom>10000)throw Error('Bitte positive Durchschnittspreise und eine gültige Vermarktungsdauer eingeben.');const uplift=dom<=rules.shortDom?rules.maxUplift:0,at=target=>price*(1+uplift-Math.min(rules.maxDiscount,Math.max(0,dom-target)*rules.discountPerDay));return {lower:at(rules.targetLower),upper:at(rules.targetUpper),averagePrice:price,averageDom:dom}}
function key(zip,rooms,type){return zip+'|'+Number(rooms)+'|'+type}
function domOverview(rows){const groups=[{id:'fast',label:'Bis 60 Tage · ideal oder schneller'},{id:'limit',label:'Über 60 bis 90 Tage · Oberkante'},{id:'critical',label:'Über 90 Tage · kritisch / überteuert'}].map(g=>({...g,rows:[]}));for(const row of rows||[]){if(typeof row.price!=='number'||!Number.isFinite(row.price)||row.price<=0||typeof row.dom!=='number'||!Number.isFinite(row.dom)||row.dom<0)continue;groups[row.dom<=60?0:row.dom<=90?1:2].rows.push(row)}return groups.map(g=>{g.rows.sort((a,b)=>a.price-b.price||a.dom-b.dom);const n=g.rows.length;return {...g,count:n,averagePrice:n?g.rows.reduce((s,r)=>s+r.price,0)/n:null,averageDom:n?g.rows.reduce((s,r)=>s+r.dom,0)/n:null,minPrice:n?g.rows[0].price:null,maxPrice:n?g.rows[n-1].price:null}})}
function period(from,to){const valid=v=>/^\d{4}-\d{2}-\d{2}$/.test(v||'')&&Number.isFinite(new Date(v+'T12:00:00Z').getTime())&&new Date(v+'T12:00:00Z').toISOString().slice(0,10)===v;if(!valid(from)||!valid(to))throw Error('Bitte einen gültigen Auswertungszeitraum von/bis eingeben.');if(from>to)throw Error('Der Beginn des Zeitraums darf nicht nach dem Ende liegen.');return {periodStart:from,periodEnd:to}}
function periodLabel(a){return a.periodStart&&a.periodEnd?'Zeitraum: '+a.periodStart.split('-').reverse().join('.')+' bis '+a.periodEnd.split('-').reverse().join('.'):'Zeitraum nicht hinterlegt'}
function format(result,city,label){const n=x=>new Intl.NumberFormat('de-DE',{maximumFractionDigits:0}).format(x);return '- Fairer Preiskorridor nach Dr.-Singer-Logik (Immometrica, '+String(city).trim()+', '+String(label).trim()+'): '+n(result.lower)+' €/m² bis '+n(result.upper)+' €/m²\n- Einordnung:\n  Dieser Preiskorridor beschreibt den realistisch erzielbaren Marktpreisbereich auf Basis der aktuellen Angebotsdaten und der Vermarktungsdauer.\n- Kurzstatement:\n  „Alles darüber braucht Zeit oder Preisnachlass.“'}
function read(storage,name,fallback){try{const x=JSON.parse(storage.getItem(name)||'null');return x&&typeof x==='object'?x:fallback}catch{return fallback}}
function reference(item,zip,storage=localStorage){if(item.action==='mieten')return null;const rooms=Number(item.rooms),type=kind(item.typ);if(!/^\d{5}$/.test(zip||'')||!type||!(rooms>0))return null;const refs=read(storage,referencesKey,{}),r=refs[key(zip,rooms,type)];return r&&r.zipcode===zip&&r.rooms===rooms&&r.kind===type&&Number.isFinite(r.value)&&r.value>0?r:null}
function referenceFrom(a,basis){if(!['lower','middle','upper'].includes(basis))throw Error('Bitte einen Vergleichswert auswählen.');return {analysisId:a.id,zipcode:a.zipcode,rooms:Number(a.rooms),kind:a.kind,basis,value:basis==='middle'?(a.result.lower+a.result.upper)/2:a.result[basis],lower:a.result.lower,upper:a.result.upper,city:a.city,updatedAt:a.updatedAt}}
return {period,periodLabel,domOverview,rules,analysesKey,referencesKey,number,csv,parse,select,average,corridor,format,key,kind,read,reference,referenceFrom};})();
if(typeof module!=='undefined')module.exports=SingerCore;
